<!DOCTYPE html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QR Absensi - Hadiriin</title><style>body{background:#100c12;color:#fff;font-family:Inter,Arial,sans-serif;margin:0}nav{background:#171119;padding:18px 6%;display:flex;gap:20px;align-items:center;flex-wrap:wrap}a{color:#ff54ad;text-decoration:none}main{max-width:1000px;margin:30px auto;padding:0 18px}h1{color:#ff54ad}.panel{background:#1b151e;border:1px solid #713052;border-radius:16px;padding:24px;margin:18px 0}input,select,button{padding:12px;border-radius:9px;border:1px solid #713052;margin:6px;background:#251a28;color:white;font-size:15px}button{background:#a52d70;cursor:pointer}button:hover{background:#c83b8a}.success{color:#77e7a0}.error{color:#ff8f9c}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #473347;text-align:left}.muted{color:#b5a5b5}#qr{background:white;padding:16px;display:inline-block;border-radius:10px}video{max-width:100%}@media(max-width:600px){table{font-size:12px}td,th{padding:6px}}</style></head><body><nav><strong>Hadiriin.</strong><a href="{{route('mahasiswa.dashboard')}}">Dashboard Mahasiswa</a><a href="{{route('mahasiswa.qr.index')}}">Scan QR Absensi</a></nav><main><h1>Scan QR Absensi</h1><p class="muted">Arahkan kamera ke QR yang ditampilkan dosen. Izinkan akses kamera ketika diminta.</p>@if(session('success'))<div class="panel success">{{session('success')}}</div>@endif @foreach($errors->all() as $e)<div class="panel error">{{$e}}</div>@endforeach<div class="panel"><div id="reader" style="max-width:450px"></div><p id="scan-status" class="muted">Tekan tombol untuk mengaktifkan kamera.</p><button type="button" id="start">Mulai Scan Kamera</button><button type="button" id="stop">Hentikan Kamera</button><form id="scan-form" method="POST" action="{{route('mahasiswa.attendance.scan')}}">@csrf<label>Atau masukkan kode QR secara manual <input name="qr" id="qr-input" required style="width:90%" placeholder="ID:slot:signature"></label><button type="submit">Kirim Absensi</button></form></div><div class="panel"><h2>Riwayat Kehadiran</h2><table><tr><th>Sesi</th><th>Waktu</th><th>Status</th></tr>@forelse($riwayat as $a)<tr><td>{{$a->sesiAbsensi?->judul}}</td><td>{{$a->waktu_absen?->format('d M Y H:i')}}</td><td>{{$a->status}}</td></tr>@empty<tr><td colspan="3">Belum ada absensi.</td></tr>@endforelse</table></div></main><script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script><script>
let scanner=null,submitting=false;const status=document.getElementById('scan-status');document.getElementById('start').onclick=async()=>{if(scanner)return;if(typeof Html5Qrcode==='undefined'){status.textContent='Library scanner gagal dimuat. Periksa internet.';return;}try{scanner=new Html5Qrcode('reader');await scanner.start({facingMode:'environment'},{fps:10,qrbox:{width:230,height:230}},value=>{if(submitting)return;submitting=true;document.getElementById('qr-input').value=value;status.textContent='QR terbaca. Mengirim absensi...';scanner.stop().catch(()=>{}).finally(()=>document.getElementById('scan-form').submit());},()=>{});status.textContent='Kamera aktif. Arahkan ke QR dosen.';}catch(e){status.textContent='Tidak dapat mengakses kamera: '+e;scanner=null;}};document.getElementById('stop').onclick=async()=>{if(scanner){try{await scanner.stop();await scanner.clear();}catch(e){}scanner=null;status.textContent='Kamera dihentikan.';}};
</script></body></html>